package com.triphuddle.api.chat.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.util.ArrayList;
import java.util.List;

/**
 * Request body for sending a message; it needs a body, attachments or both.
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class SendMessageRequest {

    // Generated by the client once per message, so that a retried send does not post it twice.
    @NotBlank(message = "Client message ID is required")
    @Size(max = 64, message = "Client message ID cannot exceed 64 characters")
    private String clientMessageId;

    @Size(max = 4000, message = "Message cannot exceed 4000 characters")
    private String body;

    private String replyToMessageId;

    @Valid
    @Size(max = 10, message = "A message cannot have more than 10 attachments")
    private List<AttachmentRequest> attachments = new ArrayList<>();
}
